package org.apache.commons.lang3;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.ObjectStreamClass;
import java.io.OutputStream;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.SerializationUtils.ClassLoaderAwareObjectInputStream;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClassLoaderAwareObjectInputStream_resolveClass_TriageGen0Test {

    /**
     * Helper method to access the protected resolveClass method via reflection.
     */
    @SuppressWarnings("unchecked")
    private Class<?> invokeResolveClass(ClassLoaderAwareObjectInputStream stream, ObjectStreamClass desc) throws Exception {
        Method method = ClassLoaderAwareObjectInputStream.class.getDeclaredMethod("resolveClass", ObjectStreamClass.class);
        method.setAccessible(true);
        return (Class<?>) method.invoke(stream, desc);
    }

    @Test
    public void testResolveClass_SuccessWithProvidedClassLoader() throws Exception {
        // Arrange
        String className = "java.lang.String";
        ObjectStreamClass desc = mock(ObjectStreamClass.class);
        when(desc.getName()).thenReturn(className);

        // Custom classloader that can find String
        ClassLoader classLoader = ClassLoader.getSystemClassLoader();
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(is, classLoader);

        // Act
        Class<?> resolvedClass = invokeResolveClass(stream, desc);

        // Assert
        assertEquals(String.class, resolvedClass);
    }

    @Test
    public void testResolveClass_FallbackToContextClassLoader() throws Exception {
        // Arrange
        // We use a class name that is available in the system/context loader 
        // but we will simulate the first loader failing by using a dummy loader.
        String className = "java.lang.Integer";
        ObjectStreamClass desc = mock(ObjectStreamClass.class);
        when(desc.getName()).thenReturn(className);

        // A classloader that will definitely throw ClassNotFoundException
        ClassLoader failingClassLoader = new ClassLoader() {
            @Override
            protected Class<?> findClass(String name) throws ClassNotFoundException {
                throw new ClassNotFoundException(name);
            }
        };

        InputStream is = new ByteArrayInputStream(new byte[0]);
        ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(is, failingClassLoader);

        // Act
        Class<?> resolvedClass = invokeResolveClass(stream, desc);

        // Assert
        assertEquals(Integer.class, resolvedClass);
    }

    @Test(expected = Exception.class)
    public void testResolveClass_ThrowsExceptionWhenNotFoundInBothLoaders() throws Exception {
        // Arrange
        String nonExistentClassName = "com.nonexistent.FakeClass";
        ObjectStreamClass desc = mock(ObjectStreamClass.class);
        when(desc.getName()).thenReturn(nonExistentClassName);

        // A loader that fails for everything
        ClassLoader failingClassLoader = new ClassLoader() {
            @Override
            protected Class<?> findClass(String name) throws ClassNotFoundException {
                throw new ClassNotFoundException(name);
            }
        };

        // Set context classloader to a failing one as well to ensure the catch block also fails
        ClassLoader originalContextClassLoader = Thread.currentThread().getContextClassLoader();
        try {
            Thread.currentThread().setContextClassLoader(failingClassLoader);

            InputStream is = new ByteArrayInputStream(new byte[0]);
            ClassLoaderAwareObjectInputStream stream = new ClassLoaderAwareObjectInputStream(is, failingClassLoader);

            // Act
            invokeResolveClass(stream, desc);
        } finally {
            Thread.currentThread().setContextClassLoader(originalContextClassLoader);
        }
    }
}

/**
 * Dummy ObjectStreamClass interface/class if not available in scope, 
 * though normally it's java.io.ObjectStreamClass.
 * Since the prompt uses it as a parameter, we assume it's the standard one.
 */
